import sys
sys.dont_write_bytecode=True
from pathlib import Path
import json,hashlib,re,struct
ROOT=Path('D:/Prog/simant_recon');OUT=ROOT/'build/workers/enhanced-design';WIN=Path('D:/Prog/simantw_recon')
sys.path.insert(0,str(WIN/'tools'))
import ne,mapsym
game=Path('D:/Games/ANTWIN');image=ne.parse((game/'SIMANTW.EXE').read_bytes());symbols=mapsym.parse((game/'SIMANTW.SYM').read_bytes())
interesting=re.compile(r'Ribbon|Scroll|Menu|Help|UserButton|BookMark|Window|WndProc|DoMouse|Capture',re.I)
audit={'files':{p.name:{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in [game/'SIMANTW.EXE',game/'SIMANTW.SYM',game/'SIMANT.HLP']},'header':image['header'],'modules':image['modules'],'imports':image['imports'],'resources':image['resources'],'symbols':[dict(segment=s['name'],**v) for s in symbols['segments'] for v in s['symbols'] if interesting.search(v['name'])],'help_header_hex':(game/'SIMANT.HLP').read_bytes()[:16].hex()}
ds=next(s for s in symbols['segments'] if s['name']=='DGROUP');base=image['segments'][ds['number']-1]['file_offset'];raw=(game/'SIMANTW.EXE').read_bytes()
audit['initial_user_buttons']={n:{'symbol_offset':o,'values':list(struct.unpack_from('<8h',raw,base+o))} for n,o in [('mapUserButton',18),('yardUserButton',34)]}
(OUT/'win16-binary-audit.json').write_text(json.dumps(audit,indent=2))
data=json.loads((OUT/'resource-inventory.json').read_text(encoding='utf-8'))
values={};names={}
for l in (ROOT/'include/windows_ids.h').read_text().splitlines():
    m=re.match(r'#define\s+(\w+)\s+(.+)',l)
    if m:
        try:
            value=eval(m[2],{'__builtins__':{}},values);values[m[1]]=value;names.setdefault(value,[]).append(m[1])
        except Exception:pass
handler={0:'ProcEditEvent',1:'ProcMapEvent',2:'DoScenario wait',3:'ShowIntro wait',4:'EndGameDialog wait',5:'ProcInfoEvent / link records',6:'EditScentMenu / win_DoProxMenu',7:'AntMenu / win_DoProxMenu',8:'AntMenu / win_DoProxMenu',9:'DoExpMenu',10:'EditToolsMenu / MapToolsMenu',11:'EditToolsMenu / MapToolsMenu',12:'DoExpMenu submenu',13:'DoExpMenu submenu',14:'DoExpMenu submenu',15:'DoExpMenu submenu',16:'DoExpMenu submenu',17:'DoExpMenu submenu',18:'ProcModeEvent',19:'ProcCasteEvent',20:'OpenMiniMapWin wait',21:'ProcHistoryEvent',22:'FileSelect',23:'DrawCastePopUp wait',24:'ScoreDialog wait',25:'ProcYardEvent',26:'YellowDialog / YellowHelp / LionDialog / SpiderDialog wait',27:'continuation wait',28:'debug only; opener unestablished',29:'MagnifyMenu wait',30:'PictureDialog wait',31:'AboutDialog',32:'AntMenu spider branch',33:'save-confirmation wait'}
roles={0:'native container styling',1:'native custom view/hit region',2:'native container background',4:'native list',5:'native push/toggle/radio button',6:'native image or image-button asset',7:'native scrollbar in lists only',8:'native scrollbar in lists only',9:'native static text',12:'native caption (no emulated title strip)',13:'native image-button',15:'native border styling',16:'native formatted text',17:'native formatted button',18:'native caption',19:'native separator',20:'native separator',21:'native container border',22:'native container border'}
rows=[]
for a in data['dos']:
    if a.get('kind')!=0 or a['id']>33 or 'objects' not in a:continue
    for ob in a['objects']['objects']:
        code=a['id']*256+ob['index'];selectable=bool(ob['flags']&2)
        role=roles.get(ob['type'],'native custom semantic view')
        if a['id']==0 and ob['index']==4:role='native world canvas; no scroll bars or VGA input surface'
        if a['id']==1 and ob['index']==2:role='native overview world canvas'
        if a['id']==25 and ob['index']==2:role='native yard canvas'
        if a['id'] in range(6,18) and selectable:role='native menu item / tool selection'
        structural=ob['index']==0 or ob['type'] in (12,18)
        if ob['index']==0:role='native host/container; discard DOS frame geometry'
        if a['id'] in (18,19) and ob['index']==13:role='native triangle control with UIA and keyboard'
        if a['id']==21 and ob['index']==14:role='native plot canvas plus accessible data table'
        sends='none; native docking/move/resize is presentation only' if structural else (f'0x{code:04X} through {handler[a["id"]]}' if selectable else 'none (view/style); any source runtime visibility/selectability change must be mirrored')
        rows.append({'id':f'{code:04X}','names':names.get(code,[]),'type':ob['type'],'flags':f'{ob["flags"]:04X}','native':role,'reads':'canonical object visible/enabled/selected/text state; semantic window view in DESIGN.md','sends':sends,'resource':f'HCEGANT kind 0 id {a["id"]} object {ob["index"]}'})
(OUT/'control-ledger.json').write_text(json.dumps(rows,indent=2))
out=['# Complete shipped DOS object census and native disposition','','Generated by `reference_audit.py` from the decoded resource inventory and `include/windows_ids.h`. This is an object census, not a claim that all native bindings have been implemented or runtime-proven. The detailed semantic reads/actions and unresolved special cases are in DESIGN.md. Type/flags are the shipped initial values; runtime object state wins. Original layout rectangles are compatibility inputs only, never the native layout.','','All canonical controls use the source event dispatcher/wait listed below. No native widget writes canonical state directly. Render-only objects send no events; selectable controls require activation-before-delivery and source flags/selection handling, as specified in DESIGN.md. High-bit help pictures, graph palettes and layout anchors are data, not additional user controls.','','| Object | Descriptive alias | Type / flags | Native disposition | Sends / source consumer |','|---|---|---|---|---|']
for a in rows:out.append('| '+a['id']+' | '+', '.join(a['names'])+' | '+str(a['type'])+' / '+a['flags']+' | '+a['native']+' | '+a['sends']+' |')
(OUT/'CONTROL-MAP.md').write_text('\n'.join(out)+'\n',encoding='utf-8')
print(json.dumps({'objects':len(rows),'win_symbols':len(audit['symbols']),'exe_sha256':audit['files']['SIMANTW.EXE']['sha256']}))
